export const QUEUED_ENTRY_TAG = 1n << 46n;
/** Purchase buffer/position -> settlement reference; without a position it is the bare RNG index. */
export function boxReference(index, position) {
  if (position == null) return BigInt(index);
  const buffer = BigInt(index), p = BigInt(position);
  if (buffer < 0n || buffer > 1n || p < 0n || p > 0xffffffffn) throw new RangeError('Invalid box queue position.');
  return QUEUED_ENTRY_TAG | (p << 1n) | buffer;
}
export function boxQueuePosition(reference) {
  const ref = BigInt(reference);
  if (ref < QUEUED_ENTRY_TAG || ref >= 2n * QUEUED_ENTRY_TAG) return null;
  return { buffer: ref & 1n, position: (ref & (QUEUED_ENTRY_TAG - 1n)) >> 1n };
}
